submit() {
  local WIRE="$1"
  local URL="$2"
  local RAW="$3"

  # Duplicate check via DB
  EXISTS=$(psql "$DB" -At -c "SELECT 'EXISTS:' || status FROM scan_entries WHERE source_url = '$URL' LIMIT 1;" 2>/dev/null)

  if [[ -z "$EXISTS" ]]; then
    echo "[SUBMIT] $WIRE | $URL"
    curl -sf -X POST "$API/api/scan/submit" \
      -H "Authorization: Bearer $TOKEN" \
      -H "Content-Type: application/json" \
      -d "$(jq -n \
        --arg wire "$WIRE" \
        --arg date "$DATE" \
        --arg raw "$RAW" \
        '{wire: $wire, promptVariant: "A", scanDate: $date, rawText: $raw, source: "web-search"}')"
    echo ""
  else
    echo "[SKIP] $WIRE | $EXISTS | $URL"
  fi
}

